require_once __DIR__.'/../config/config.php';require_role(['admin']);$id=(int)($_GET['id']??0);$person=null;if($id){$s=db()->prepare("SELECT id,name,email,role,status FROM users WHERE id=?");$s->execute([$id]);$person=$s->fetch();if(!$person)exit('User not found.');}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$role=$_POST['role']??'student';$status=$_POST['status']??'active';if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||!in_array($role,['student','teacher','admin'],true)||!in_array($status,['active','suspended'],true)){flash('Please check the form values.','error');redirect('/admin/user-edit.php'.($id?'?id='.$id:''));}if($id){$s=db()->prepare("UPDATE users SET name=?,email=?,role=?,status=? WHERE id=?");$s->execute([$name,$email,$role,$status,$id]);if(!empty($_POST['password'])){if(strlen($_POST['password'])<10)exit('Password must be at least 10 characters.');$s=db()->prepare("UPDATE users SET password_hash=? WHERE id=?");$s->execute([password_hash($_POST['password'],PASSWORD_DEFAULT),$id]);}}else{if(strlen($_POST['password']??'')<10)exit('Password must be at least 10 characters.');$s=db()->prepare("INSERT INTO users(name,email,password_hash,role,status) VALUES(?,?,?,?,?)");$s->execute([$name,$email,password_hash($_POST['password'],PASSWORD_DEFAULT),$role,$status]);}flash('User saved.');redirect('/admin/index.php');}
$page_title='Manage user — LinguaFree';include __DIR__.'/../includes/header.php'; ?>
<div class="page-head"><div><span class="eyebrow">USER MANAGEMENT</span><h1><?= $person?'Edit user':'Create user' ?></h1></div></div><form class="form-card" method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><label>Name<input name="name" required value="<?= e($person['name']??'') ?>"></label><label>Email<input type="email" name="email" required value="<?= e($person['email']??'') ?>"></label><label>Password <?= $id?'(leave blank to keep current)':'' ?><input type="password" name="password" <?= $id?'':'required' ?> minlength="10"></label><label>Role<select name="role"><?php foreach(['student','teacher','admin'] as $r): ?><option <?= ($person['role']??'student')===$r?'selected':'' ?>><?= $r ?></option><?php endforeach; ?></select></label><label>Status<select name="status"><option value="active" <?= ($person['status']??'active')==='active'?'selected':'' ?>>Active</option><option value="suspended" <?= ($person['status']??'')==='suspended'?'selected':'' ?>>Suspended</option></select></label><button class="btn btn-primary">Save user →</button></form>
